package net.oceancanvas.mod.worldgen;
import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class OceanCanvasFutureObservationTest {
 @Test void absentAndPendingNeverInvokeDecoderOrWait(){var calls=new AtomicInteger();var f=new CompletableFuture<Boolean>();assertEquals("ABSENT",OceanCanvasFutureObservation.state(null,v->{calls.incrementAndGet();return true;}));assertEquals("PENDING",OceanCanvasFutureObservation.state(f,v->{calls.incrementAndGet();return true;}));assertEquals(0,calls.get());assertEquals(0,f.getNumberOfDependents());assertFalse(f.isDone());}
 @Test void terminalOutcomesRemainUnchanged(){var ok=CompletableFuture.completedFuture(true);var unloaded=CompletableFuture.completedFuture(false);assertEquals("SUCCESS",OceanCanvasFutureObservation.state(ok,v->v));assertEquals("UNLOADED",OceanCanvasFutureObservation.state(unloaded,v->v));assertTrue(ok.getNow(false));assertFalse(unloaded.getNow(true));assertEquals("DONE_NULL",OceanCanvasFutureObservation.state(CompletableFuture.completedFuture(null),v->true));}
 @Test void cancellationAndExceptionalDoNotExposeDetailsOrCallDecoder(){var f=new CompletableFuture<Boolean>();f.cancel(false);assertEquals("CANCELLED",OceanCanvasFutureObservation.state(f,v->{fail();return true;}));var error=new CompletableFuture<Boolean>();error.completeExceptionally(new RuntimeException("sensitive"));assertEquals("EXCEPTIONAL",OceanCanvasFutureObservation.state(error,v->{fail();return true;}));assertTrue(error.isCompletedExceptionally());assertEquals(0,error.getNumberOfDependents());}
 @Test void decoderFailureIsUnavailableAndOriginalUntouched(){var f=CompletableFuture.completedFuture(true);assertEquals("UNAVAILABLE",OceanCanvasFutureObservation.state(f,v->{throw new IllegalStateException("sensitive");}));assertTrue(f.getNow(false));}
}
